import json, sys


def solve(request):
    mem0 = tuple(request["memory"])
    instrs = [list(t) for t in request["threads"]]
    nt = len(instrs)

    start = ((0,) * nt, tuple(() for _ in range(nt)), mem0, tuple(() for _ in range(nt)))
    seen = {start}
    stack = [start]
    outcomes = set()

    while stack:
        pcs, bufs, mem, reads = stack.pop()

        if all(pcs[i] >= len(instrs[i]) for i in range(nt)) and not any(bufs):
            outcomes.add((reads, mem))
            continue

        for i in range(nt):
            pc = pcs[i]
            if pc >= len(instrs[i]):
                continue
            ins = instrs[i][pc]
            op = ins[0]
            buf = bufs[i]

            if op == "store":
                a, w, v = ins[1], ins[2], ins[3]
                nb = buf + ((a, w, v),)
                st = (pcs[:i] + (pc + 1,) + pcs[i + 1:],
                      bufs[:i] + (nb,) + bufs[i + 1:], mem, reads)
                if st not in seen:
                    seen.add(st)
                    stack.append(st)
            elif op == "load":
                a, w = ins[1], ins[2]
                val = 0
                for k in range(w):
                    addr = a + k
                    byte = None
                    for (sa, sw, sv) in reversed(buf):
                        if sa <= addr < sa + sw:
                            byte = (sv >> (8 * (addr - sa))) & 0xFF
                            break
                    if byte is None:
                        byte = mem[addr]
                    val |= byte << (8 * k)
                nr = reads[i] + (val,)
                st = (pcs[:i] + (pc + 1,) + pcs[i + 1:], bufs, mem,
                      reads[:i] + (nr,) + reads[i + 1:])
                if st not in seen:
                    seen.add(st)
                    stack.append(st)
            elif op == "fence":
                if not buf:
                    st = (pcs[:i] + (pc + 1,) + pcs[i + 1:], bufs, mem, reads)
                    if st not in seen:
                        seen.add(st)
                        stack.append(st)
            else:  # xchg
                if not buf:
                    a, w, v = ins[1], ins[2], ins[3]
                    val = 0
                    for k in range(w):
                        val |= mem[a + k] << (8 * k)
                    nm = list(mem)
                    for k in range(w):
                        nm[a + k] = (v >> (8 * k)) & 0xFF
                    nr = reads[i] + (val,)
                    st = (pcs[:i] + (pc + 1,) + pcs[i + 1:], bufs, tuple(nm),
                          reads[:i] + (nr,) + reads[i + 1:])
                    if st not in seen:
                        seen.add(st)
                        stack.append(st)

        for i in range(nt):
            buf = bufs[i]
            if buf:
                a, w, v = buf[0]
                nm = list(mem)
                for k in range(w):
                    nm[a + k] = (v >> (8 * k)) & 0xFF
                st = (pcs, bufs[:i] + (buf[1:],) + bufs[i + 1:], tuple(nm), reads)
                if st not in seen:
                    seen.add(st)
                    stack.append(st)

    return {"outcomes": [
        {"reads": [list(r) for r in reads], "memory": list(mem)}
        for reads, mem in outcomes
    ]}


